CREATE TABLE public.digital_key_inventory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_slug text NOT NULL, license_key text NOT NULL UNIQUE, order_id uuid UNIQUE REFERENCES public.digital_orders(id), assigned_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.digital_key_inventory TO service_role;
ALTER TABLE public.digital_key_inventory ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.digital_orders ADD COLUMN IF NOT EXISTS delivery_access_hash text;
CREATE OR REPLACE FUNCTION public.allocate_digital_key(p_order uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE o public.digital_orders; k public.digital_key_inventory; BEGIN SELECT * INTO o FROM public.digital_orders WHERE id=p_order FOR UPDATE; IF NOT FOUND OR o.status NOT IN ('paid','delivered') OR o.product_slug <> 'chatgpt-plus-renew' THEN RETURN false; END IF; SELECT * INTO k FROM public.digital_key_inventory WHERE order_id=p_order; IF NOT FOUND THEN SELECT * INTO k FROM public.digital_key_inventory WHERE product_slug=o.product_slug AND order_id IS NULL ORDER BY created_at,id FOR UPDATE SKIP LOCKED LIMIT 1; IF NOT FOUND THEN UPDATE public.digital_orders SET delivery_status='failed',delivery_error='Key inventory unavailable' WHERE id=p_order; RETURN false; END IF; UPDATE public.digital_key_inventory SET order_id=p_order,assigned_at=now() WHERE id=k.id; END IF; UPDATE public.digital_orders SET status='delivered',delivery_status='delivered',delivery_payload=k.license_key,delivery_error=NULL WHERE id=p_order; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.allocate_digital_key(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.allocate_digital_key(uuid) TO service_role;